        for (int i = 0; i < n; ++i) {
            int fact = 1;
            for (int j = 1; j < n - i; ++j) {
                fact *= j;
            }
            for (int j = 1; j <= n; ++j) {
                if (((vis >> j) & 1) == 0) {
                    if (k > fact) {
                        k -= fact;
                    } else {
                        ans.Append(j);
                        vis |= 1 << j;
                        break;
                    }
                }
            }
        }
        return ans.ToString();
    }
}

function getPermutation(n: number, k: number): string {
    let ans = '';
    const vis = Array.from({ length: n + 1 }, () => false);
    for (let i = 0; i < n; i++) {
        let fact = 1;
        for (let j = 1; j < n - i; j++) {
            fact *= j;
        }
        for (let j = 1; j <= n; j++) {
            if (!vis[j]) {
                if (k > fact) {
                    k -= fact;
                } else {
                    ans += j;
                    vis[j] = true;
                    break;
                }
            }
        }
    }
    return ans;
}

class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> fact(1, 1);
        for (int i = 1; i <= n; i++) {
            fact.push_back(fact[i - 1] * i);
        }
        string res = "";
        vector<char> chars(n);
        int pos;
        k--;
        for (int i = 0; i < n; i++)
            chars[i] = '0' + i + 1;
        while (--n) {
            pos = k / fact[n];
            res += chars[pos];
            chars.erase(begin(chars) + pos);
            k %= fact[n];
        }
        return res;
    }
};

